export type MathLesson={title:string;module:string;body:string;example:string;question:string;options:[string,string,string];correct:number};
const catalog:Record<string,[string,string,string,string,string,[string,string,string],number][]>= {"Porcentagem":[["Conceito de porcentagem","Fundamentos","Porcentagem é uma razão por 100. O símbolo % significa 'a cada cem'.","25% = 25/100 = 1/4.","Qual fração representa 40%?",["40/100","40/10","100/40"],0],["Porcentagem e frações","Fundamentos","Converta o percentual em fração de denominador 100 e simplifique.","50% = 50/100 = 1/2.","Quanto é 75% como fração simplificada?",["1/4","3/4","4/3"],1],["Porcentagem e decimais","Fundamentos","Divida o percentual por 100 para escrever em decimal.","12% = 0,12; 125% = 1,25.","Quanto é 8% em decimal?",["0,8","0,08","8"],1],["Cálculo de porcentagens","Fundamentos","Multiplique a quantidade pela taxa escrita como decimal.","15% de 200 = 0,15 × 200 = 30.","Quanto é 20% de 150?",["20","30","50"],1],["Descobrir a taxa percentual","Fundamentos","Divida a parte pelo total e multiplique por 100.","18 de 60 = 18/60 × 100 = 30%.","12 é quantos por cento de 48?",["25%","36%","48%"],0],["Descobrir o valor total","Fundamentos","Divida a parte conhecida pela taxa decimal para recuperar o total.","Se 20% são 40, o total é 40/0,2 = 200.","Se 25% são 30, qual é o total?",["75","120","150"],1],["Descontos simples","Aplicações","O preço final após desconto é o original multiplicado por (1 − taxa).","R$ 80 com 15% de desconto: 80 × 0,85 = R$ 68.","R$ 200 com desconto de 10% custa quanto?",["R$ 180","R$ 190","R$ 210"],0],["Acréscimos simples","Aplicações","O preço final após aumento é o original multiplicado por (1 + taxa).","R$ 100 com aumento de 12% passa a R$ 112.","R$ 50 com acréscimo de 20% passa a:",["R$ 60","R$ 70","R$ 55"],0],["Aumentos sucessivos","Aplicações","Percentuais sucessivos são multiplicativos, não simplesmente somados.","Dois aumentos de 10%: 1,1 × 1,1 = 1,21; aumento total de 21%.","Dois aumentos de 10% equivalem a:",["20%","21%","22%"],1],["Descontos sucessivos","Aplicações","Aplique cada desconto sobre o novo valor, não sobre o original.","R$ 100 com descontos de 10% e 20%: 100 × 0,9 × 0,8 = 72.","Dois descontos de 10% sobre R$ 100 resultam em:",["R$ 80","R$ 81","R$ 90"],1],["Variação percentual","Aplicações","Divida a diferença pelo valor inicial e multiplique por 100.","De 80 para 100: (100−80)/80 = 25%.","De 50 para 60 houve aumento de:",["10%","20%","25%"],1],["Percentuais acima de 100%","Aplicações","Percentuais superiores a 100% representam valores maiores que o inteiro.","150% de 40 = 1,5 × 40 = 60.","Quanto é 200% de 35?",["35","70","200"],1],["Pontos percentuais","Aprofundamento","A diferença entre duas taxas em % é medida em pontos percentuais; não confunda com variação relativa.","De 10% para 15%: +5 pontos percentuais, ou +50% relativo.","De 30% para 35% há aumento de:",["5 pontos percentuais","35 pontos percentuais","5% relativo"],0],["Juros simples","Aprofundamento","Nos juros simples, os juros incidem sobre o capital inicial: J = C × i × t.","R$ 1.000 a 2% ao mês por 3 meses: J = R$ 60.","R$ 500 a 2% ao mês por 2 meses gera juros de:",["R$ 10","R$ 20","R$ 40"],1],["Juros compostos","Aprofundamento","Nos juros compostos, cada período atualiza o saldo: M = C × (1+i)^t.","R$ 100 a 10% por 2 períodos: 100 × 1,1² = R$ 121.","R$ 200 a 10% por 2 períodos resulta em:",["R$ 220","R$ 240","R$ 242"],2],["Inflação e poder de compra","Aprofundamento","Uma alta de preços reduz o poder de compra se a renda não acompanha a variação.","Produto de R$ 50 com alta de 8% passa a R$ 54.","Produto de R$ 100 com inflação de 5% custa:",["R$ 95","R$ 105","R$ 150"],1],["Porcentagem em gráficos","Domínio","Interprete o percentual como parcela do total; a soma das categorias exclusivas deve ser 100%.","Em 200 alunos, 35% correspondem a 70 alunos.","40% de 250 participantes correspondem a:",["100","125","150"],0],["Problemas integrados","Domínio","Identifique a base de cálculo, diferencie descontos de aumentos e confira as unidades.","R$ 120 com 25% de desconto: R$ 90; com 10% de aumento: R$ 99.","R$ 80 com 25% de desconto e depois 20% de aumento resulta em:",["R$ 76","R$ 72","R$ 80"],1]],"Álgebra":[["Expressões algébricas","Fundamentos","Uma expressão combina números, variáveis e operações; letras representam valores.","3x+2 com x=4 vale 14.","Quanto vale 2x+1 para x=5?",["10","11","12"],1],["Variáveis e constantes","Fundamentos","Uma variável pode assumir valores; uma constante mantém seu valor em uma expressão.","Em 4x+7, x é variável e 7 é constante.","Em 5y+3, qual símbolo é variável?",["5","y","3"],1],["Termos e coeficientes","Fundamentos","O coeficiente é o número que multiplica a variável em um termo.","Em 7x, o coeficiente é 7.","Qual é o coeficiente de 9a?",["a","9","0"],1],["Termos semelhantes","Fundamentos","Termos com a mesma parte literal e expoentes iguais podem ser somados.","3x+5x=8x.","Quanto é 4y+2y?",["6y","8y","6y²"],0],["Propriedade distributiva","Fundamentos","Multiplique o fator externo por cada termo dentro dos parênteses.","3(x+2)=3x+6.","Quanto é 2(a+4)?",["2a+4","2a+8","a+8"],1],["Potências algébricas","Fundamentos","Ao multiplicar potências de mesma base, somam-se os expoentes.","x² × x³ = x⁵.","Quanto é a² × a⁴?",["a⁶","a⁸","a²"],0],["Equações do primeiro grau","Equações","Isole a incógnita realizando operações equivalentes nos dois membros.","x+7=12, então x=5.","Se x+8=20, quanto vale x?",["12","28","8"],0],["Equações com multiplicação","Equações","Para resolver ax=b, divida ambos os lados por a, com a diferente de zero.","4x=28, logo x=7.","Se 6x=42, x vale:",["6","7","8"],1],["Equações com parênteses","Equações","Aplique a distributiva e agrupe os termos semelhantes antes de isolar x.","2(x+3)=14 → 2x+6=14 → x=4.","Se 3(x+2)=15, x vale:",["3","5","7"],0],["Equações com frações","Equações","Multiplique ambos os membros pelo denominador não nulo para eliminar a fração.","x/3=5 → x=15.","Se x/4=6, x vale:",["10","24","2"],1],["Inequações","Equações","Uma inequação usa <, >, ≤ ou ≥. Ao multiplicar por número negativo, inverta o sinal.","−2x<6 implica x>−3.","Se x+2>7, então:",["x>5","x<5","x=5"],0],["Sistemas lineares","Equações","Resolva duas equações simultaneamente por substituição ou eliminação.","x+y=10 e x−y=2 dão x=6, y=4.","Se x+y=8 e x−y=2, qual é x?",["3","5","6"],1],["Produtos notáveis","Aprofundamento","O quadrado da soma segue (a+b)²=a²+2ab+b².","(x+2)²=x²+4x+4.","Qual é (x+3)²?",["x²+9","x²+6x+9","x²+3x+9"],1],["Fatoração por evidência","Aprofundamento","Coloque o fator comum dos termos em evidência.","6x+9=3(2x+3).","Qual é a fatoração de 4x+8?",["4(x+2)","4(x+8)","x(4+8)"],0],["Diferença de quadrados","Aprofundamento","A identidade a²−b²=(a−b)(a+b) permite fatorar expressões.","x²−16=(x−4)(x+4).","Qual fatoração corresponde a x²−9?",["(x−3)²","(x−3)(x+3)","(x+9)(x−1)"],1],["Equação do segundo grau","Aprofundamento","Na equação ax²+bx+c=0, com a≠0, é possível usar fatoração ou fórmula quadrática.","x²−5x+6=0 tem raízes 2 e 3.","Quais são as raízes de x²−4=0?",["0 e 4","−2 e 2","−4 e 4"],1],["Discriminante","Aprofundamento","O discriminante Δ=b²−4ac indica a natureza das raízes reais.","x²−4x+4: Δ=16−16=0.","Para x²−6x+9, Δ vale:",["0","9","36"],0],["Problemas com equações","Domínio","Traduza o texto para uma equação, resolva e confira no contexto.","O dobro de um número mais 3 é 17: 2x+3=17 → x=7.","O triplo de um número é 27. O número é:",["6","9","12"],1]],"Geometria":[["Pontos, retas e planos","Fundamentos","Ponto indica posição; reta é ilimitada em duas direções; plano é uma superfície ideal ilimitada.","Dois pontos distintos determinam uma reta.","Quantos pontos distintos determinam uma reta?",["1","2","3"],1],["Segmentos e semirretas","Fundamentos","Segmento possui duas extremidades; semirreta possui origem e se prolonga em uma direção.","O lado de um triângulo pode ser representado por um segmento.","Qual figura possui duas extremidades?",["Reta","Semirreta","Segmento"],2],["Ângulos e medidas","Fundamentos","Ângulos medem a abertura entre semirretas; são expressos em graus ou radianos.","Ângulo reto mede 90°.","Qual medida corresponde a um ângulo raso?",["90°","180°","360°"],1],["Triângulos","Fundamentos","Triângulos têm três lados e a soma dos ângulos internos é 180°.","Se dois ângulos medem 50° e 60°, o terceiro mede 70°.","Um triângulo tem ângulos 40° e 60°. O terceiro é:",["80°","100°","120°"],0],["Quadriláteros","Fundamentos","Quadriláteros têm quatro lados e soma dos ângulos internos de 360°.","Um retângulo tem quatro ângulos retos.","Qual quadrilátero tem quatro ângulos retos?",["Retângulo","Trapézio qualquer","Losango qualquer"],0],["Polígonos","Fundamentos","Polígono é uma figura plana fechada formada por segmentos de reta.","Um pentágono possui cinco lados.","Quantos lados tem um hexágono?",["5","6","8"],1],["Perímetro","Medidas","Perímetro é a soma das medidas de todos os lados da figura.","Retângulo 3 cm × 5 cm: perímetro 2(3+5)=16 cm.","Quadrado de lado 7 cm tem perímetro:",["14 cm","28 cm","49 cm"],1],["Área de quadrados","Medidas","A área de um quadrado é lado × lado, expressa em unidades quadradas.","Quadrado de lado 6 cm: área 36 cm².","Área de quadrado de lado 4 cm:",["8 cm²","16 cm²","12 cm²"],1],["Área de retângulos","Medidas","A área do retângulo é base × altura.","Retângulo 8 m × 3 m: área 24 m².","Retângulo 5 cm × 7 cm tem área:",["12 cm²","24 cm²","35 cm²"],2],["Área de triângulos","Medidas","A área do triângulo é base × altura ÷ 2.","Base 10 cm, altura 4 cm: área 20 cm².","Triângulo de base 6 cm e altura 5 cm tem área:",["15 cm²","30 cm²","11 cm²"],0],["Circunferência e círculo","Medidas","Circunferência é a linha; círculo é a região interna. O comprimento é 2πr e a área é πr².","Raio 3 cm: área 9π cm².","Um círculo de raio 2 cm tem área:",["2π cm²","4π cm²","8π cm²"],1],["Teorema de Pitágoras","Aprofundamento","Em triângulos retângulos, a²+b²=c², sendo c a hipotenusa.","Catetos 3 e 4: hipotenusa 5.","Catetos 6 e 8: hipotenusa:",["10","12","14"],0],["Semelhança de triângulos","Aprofundamento","Triângulos semelhantes têm ângulos correspondentes iguais e lados proporcionais.","Lados 3,4,5 ampliados por 2 viram 6,8,10.","Se a razão de ampliação é 3, lado 4 vira:",["7","12","16"],1],["Escala geométrica","Aprofundamento","Escala é a razão entre medidas do desenho e do objeto real, usando unidades compatíveis.","Escala 1:100: 2 cm no desenho são 200 cm reais.","Na escala 1:50, 3 cm no desenho equivalem a:",["150 cm","50 cm","15 cm"],0],["Sólidos geométricos","Espaço","Sólidos têm três dimensões: comprimento, largura e altura. Prismas e pirâmides são exemplos.","Um cubo possui 6 faces quadradas.","Quantas faces tem um cubo?",["4","6","8"],1],["Volume de paralelepípedos","Espaço","Volume de um bloco retangular é comprimento × largura × altura.","2 cm × 3 cm × 4 cm = 24 cm³.","Volume de 3 × 4 × 5 cm é:",["12 cm³","20 cm³","60 cm³"],2],["Volume de cilindros","Espaço","Volume do cilindro é área da base circular vezes altura: πr²h.","Raio 2 e altura 3: volume 12π.","Cilindro de raio 1 e altura 5 tem volume:",["5π","10π","25π"],0],["Coordenadas cartesianas","Espaço","No plano cartesiano, cada ponto é identificado pelo par ordenado (x,y).","O ponto (3,2) fica três unidades à direita e duas acima da origem.","No ponto (4,−2), a coordenada y é:",["4","−2","2"],1]],"Funções":[["Relações entre grandezas","Fundamentos","Uma relação associa valores de dois conjuntos. Uma função atribui exatamente uma saída a cada entrada do domínio.","Preço = 5 × quantidade é função da quantidade.","Uma função pode atribuir quantas saídas a uma entrada?",["Uma","Duas obrigatórias","Infinitas"],0],["Domínio e imagem","Fundamentos","Domínio reúne entradas permitidas; imagem reúne saídas efetivamente obtidas.","Para f(x)=x² com domínio {−1,0,1}, a imagem é {0,1}.","Na função f(x)=x², f(2) vale:",["2","4","8"],1],["Notação f(x)","Fundamentos","f(x) representa o valor da função na entrada x; substitua x na regra para calcular.","f(x)=3x+2, então f(4)=14.","Se f(x)=2x+5, f(3) é:",["8","11","16"],1],["Tabelas de valores","Fundamentos","Uma tabela organiza pares de entrada e saída para reconhecer padrões.","Para f(x)=x+2, as entradas 0,1,2 geram 2,3,4.","Para f(x)=2x, a entrada 5 gera:",["7","10","25"],1],["Plano cartesiano","Fundamentos","O gráfico de uma função reúne pontos (x,f(x)) no plano cartesiano.","Para f(x)=x+1, o ponto (2,3) pertence ao gráfico.","Qual ponto pertence a y=x+2?",["(1,3)","(1,1)","(3,1)"],0],["Função constante","Funções básicas","Uma função constante mantém a mesma saída para qualquer entrada.","f(x)=7 tem gráfico horizontal em y=7.","Se f(x)=4 para todo x, f(100) é:",["100","4","0"],1],["Função linear","Funções básicas","Função linear tem forma f(x)=ax e passa pela origem.","f(x)=3x: f(2)=6.","Se f(x)=−2x, f(3) vale:",["−6","6","−2"],0],["Função afim","Funções básicas","Função afim tem forma f(x)=ax+b; a é a inclinação e b é a interseção com o eixo y.","f(x)=2x+3 tem f(0)=3.","Em f(x)=5x+4, qual é b?",["5","4","9"],1],["Coeficiente angular","Funções básicas","Na função afim, a indica a variação da saída por unidade de entrada.","Em f(x)=3x+1, aumentar x em 1 aumenta y em 3.","Qual é a inclinação de y=−4x+2?",["2","−4","4"],1],["Raiz da função afim","Funções básicas","A raiz é a entrada que torna f(x)=0. Para ax+b=0, x=−b/a se a≠0.","2x−6=0 → x=3.","Qual é a raiz de f(x)=x−8?",["−8","0","8"],2],["Crescimento e decrescimento","Funções básicas","Na função afim, a>0 indica crescimento e a<0 indica decrescimento.","f(x)=−3x+2 é decrescente.","Qual função é crescente?",["f(x)=−x","f(x)=2x+1","f(x)=−5x+4"],1],["Função quadrática","Aprofundamento","Uma função quadrática tem forma ax²+bx+c, com a≠0, e gráfico em parábola.","f(x)=x²−4 tem raízes −2 e 2.","Qual função é quadrática?",["x+2","x²+3","5"],1],["Vértice da parábola","Aprofundamento","O vértice indica o valor mínimo quando a>0 ou máximo quando a<0.","f(x)=(x−2)²+1 tem mínimo 1 em x=2.","Qual é o mínimo de f(x)=x²+3?",["0","3","−3"],1],["Zeros da função quadrática","Aprofundamento","Zeros são as soluções da equação ax²+bx+c=0.","x²−9=0 tem zeros −3 e 3.","Quais são os zeros de x²−1?",["−1 e 1","0 e 1","1 e 2"],0],["Função exponencial","Aprofundamento","Na função exponencial f(x)=a^x, a base a é positiva e diferente de 1.","f(x)=2^x: f(3)=8.","Se f(x)=3^x, f(2) é:",["6","9","8"],1],["Função logarítmica","Aprofundamento","Logaritmo responde a qual expoente uma base deve ser elevada para gerar um número.","log₂(8)=3 porque 2³=8.","Quanto vale log₁₀(100)?",["1","2","10"],1],["Interpretação de gráficos","Aplicações","Analise intervalos de crescimento, pontos de interseção e unidades dos eixos.","Um gráfico de distância por tempo com inclinação constante indica velocidade constante.","Se y passa de 4 para 10 enquanto x cresce 2 unidades, a variação média é:",["3","6","14"],0],["Modelagem de problemas","Aplicações","Defina variáveis e formule uma função que represente uma situação real.","Táxi: bandeirada de R$ 6 mais R$ 2/km → C(x)=6+2x.","Uma corrida custa R$ 5 fixos mais R$ 3/km. Quanto custa 4 km?",["R$ 12","R$ 17","R$ 20"],1]],"Operações":[["Números naturais","Fundamentos","Números naturais são usados para contar e ordenar quantidades: 0,1,2,3,...","Após 9 vem 10.","Qual é o sucessor de 29?",["28","30","31"],1],["Adição","Fundamentos","A adição reúne parcelas e produz uma soma.","18+27=45.","Quanto é 36+19?",["45","55","65"],1],["Subtração","Fundamentos","A subtração calcula diferença ou quantidade restante.","72−28=44.","Quanto é 90−37?",["53","57","63"],0],["Multiplicação","Fundamentos","Multiplicação pode representar grupos de mesma quantidade.","6×8=48.","Quanto é 7×9?",["56","63","72"],1],["Divisão exata","Fundamentos","Divisão reparte uma quantidade em partes iguais ou mede quantos grupos cabem.","56÷7=8.","Quanto é 81÷9?",["8","9","10"],1],["Divisão com resto","Fundamentos","Se a divisão não é exata, escreva dividendo = divisor × quociente + resto.","17÷5 dá quociente 3 e resto 2.","Qual é o resto de 23÷4?",["1","2","3"],2],["Ordem das operações","Fundamentos","Resolva parênteses, potências, multiplicações e divisões, depois adições e subtrações; em mesma prioridade, siga da esquerda para a direita.","3+2×5=13.","Quanto é 8+4×3?",["36","20","24"],1],["Números inteiros","Números e sinais","Inteiros incluem negativos, zero e positivos.","−3+5=2.","Quanto é −7+10?",["−17","3","17"],1],["Soma com sinais","Números e sinais","Ao somar inteiros de sinais diferentes, subtraia os módulos e mantenha o sinal do maior módulo.","−9+4=−5.","Quanto é −12+7?",["−5","5","−19"],0],["Multiplicação com sinais","Números e sinais","Produtos com sinais iguais são positivos; com sinais diferentes são negativos.","(−4)×(−3)=12.","Quanto é (−6)×3?",["18","−18","−9"],1],["Potenciação","Números e sinais","Potência representa multiplicação repetida da mesma base.","2⁴=16.","Quanto é 3³?",["9","27","81"],1],["Radiciação","Números e sinais","A raiz quadrada principal de um número não negativo é o número não negativo cujo quadrado produz o radicando.","√49=7.","Quanto é √81?",["8","9","10"],1],["Múltiplos e divisores","Números e sinais","Múltiplos são resultados de multiplicações inteiras; divisores dividem sem resto.","12 é múltiplo de 3; 3 é divisor de 12.","Qual é divisor de 36?",["5","8","9"],2],["Números primos","Números e sinais","Número primo tem exatamente dois divisores positivos: 1 e ele mesmo.","2,3,5,7 são primos.","Qual número é primo?",["9","11","15"],1],["Frações e operações","Aplicações","Para somar frações de mesmo denominador, some numeradores; para diferentes, converta para denominador comum.","1/3+1/6=1/2.","Quanto é 1/4+1/4?",["1/8","1/2","2/8"],1],["Decimais","Aplicações","Em operações com decimais, alinhe as casas na adição e subtração; observe a vírgula na multiplicação.","1,25+2,50=3,75.","Quanto é 2,4+1,35?",["3,75","3,39","3,55"],0],["Razão e proporção","Aplicações","Razão compara grandezas; proporção expressa igualdade de razões.","2/3=4/6.","Se 2 cadernos custam R$ 10, 6 custam:",["R$ 20","R$ 30","R$ 60"],1],["Regra de três simples","Aplicações","Para grandezas diretamente proporcionais, mantenha a razão entre quantidades correspondentes.","3 kg custam R$ 24; 5 kg custam R$ 40.","Se 4 unidades custam R$ 12, 10 custam:",["R$ 24","R$ 30","R$ 36"],1],["Expressões numéricas","Domínio","Resolva operações combinadas cuidadosamente, respeitando agrupamentos e prioridade.","(12−4)×3+2=26.","Quanto é (15−5)÷2+6?",["11","16","20"],0],["Problemas do cotidiano","Domínio","Identifique dados, operação, unidades e confira se a resposta é plausível.","Três pacotes com 8 itens e mais 5 avulsos totalizam 29.","4 caixas de 6 lápis, menos 7 lápis usados: restam:",["17","24","31"],0]]};
