highSchoolCatalog["Trigonometria"].push(...([["Cosseno de 60 graus","Ângulos notáveis","Para ângulos notáveis, cos 60°=1/2. Em triângulos retângulos, o cosseno relaciona cateto adjacente e hipotenusa.","Um segmento de 12 m inclinado a 60° projeta 12×1/2=6 m na horizontal.","Qual é cos 60°?",["1/2","√3/2","1"],0],["Seno de 45 graus","Ângulos notáveis","Em um triângulo retângulo isósceles, os catetos têm o mesmo comprimento e a hipotenusa vale cateto×√2. Assim, sen 45°=√2/2.","Com catetos 1 e 1, hipotenusa √2 e sen 45°=1/√2=√2/2.","Qual é sen 45°?",["1/2","√2/2","√3/2"],1]] as typeof highSchoolCatalog["Trigonometria"]));
highSchoolCatalog["Matrizes e determinantes"].push(...([["Multiplicação por escalar","Operações","Multiplicar uma matriz por um número significa multiplicar cada elemento pelo escalar, preservando a ordem da matriz.","2×[[1,3],[2,4]]=[[2,6],[4,8]].","Qual é o elemento a₁₂ de 3×[[2,4],[1,5]]?",["7","12","15"],1],["Determinante nulo","Determinantes","Uma matriz quadrada de ordem dois possui determinante zero quando ad=bc. Nesse caso ela não tem inversa.","[[1,2],[2,4]] tem det=4−4=0.","Qual é o determinante de [[2,4],[3,6]]?",["0","12","24"],0]] as typeof highSchoolCatalog["Matrizes e determinantes"]));
highSchoolCatalog["Estatística"].push(...([["Média ponderada","Medidas de tendência central","Na média ponderada, cada valor é multiplicado por seu peso e a soma dos produtos é dividida pela soma dos pesos.","Notas 6 com peso 1 e 9 com peso 2: média=(6+18)/3=8.","Notas 5 com peso 1 e 8 com peso 3 produzem média:",["7,25","6,5","7,5"],0],["Frequência relativa","Leitura de dados","A frequência relativa é a razão entre a frequência de uma categoria e o total de observações. Multiplique por 100 para expressar em porcentagem.","Em 20 respostas, 5 escolheram A: frequência relativa 5/20=25%.","Em 40 respostas, 10 escolheram B. Qual é a frequência relativa?",["10%","25%","40%"],1]] as typeof highSchoolCatalog["Estatística"]));
highSchoolCatalog["Probabilidade"].push(...([["Probabilidade de união","Regras","Para eventos A e B, P(A∪B)=P(A)+P(B)−P(A∩B). Subtraia a interseção para não contar resultados comuns duas vezes.","No dado, A={2,4,6}, B={4,5,6}: união={2,4,5,6}, probabilidade 4/6.","Em um dado, qual é P(sair par ou sair 5)?",["1/2","2/3","5/6"],1],["Probabilidade condicional","Regras","P(A|B)=P(A∩B)/P(B) quando P(B)>0. A condição B restringe o espaço de resultados possíveis.","No dado, sabendo que saiu par, a chance de sair 6 é 1/3.","Sabendo que um dado honesto mostrou número par, qual é a chance de ter sido 2?",["1/6","1/3","1/2"],1]] as typeof highSchoolCatalog["Probabilidade"]));
highSchoolCatalog["Função afim"].push(...([["Intercepto no eixo vertical","Gráficos","Em f(x)=ax+b, o intercepto vertical é o ponto (0,b), pois f(0)=b. O coeficiente a determina a inclinação.","f(x)=4x−3 cruza o eixo vertical em (0,−3).","Onde f(x)=2x+5 cruza o eixo vertical?",["(5,0)","(0,5)","(0,2)"],1],["Taxa de variação","Aplicações","A taxa de variação média de uma função afim é constante e igual a a: (f(x₂)−f(x₁))/(x₂−x₁)=a.","Em f(x)=3x+2, aumentar x em 2 aumenta f(x) em 6.","Se f(x)=5x−1, quanto f aumenta quando x aumenta 3?",["8","15","5"],1]] as typeof highSchoolCatalog["Função afim"]));
highSchoolCatalog["Função quadrática"].push(...([["Raízes por fatoração","Equações","Quando uma expressão quadrática pode ser fatorada em dois fatores lineares, use a propriedade do produto nulo: se AB=0, então A=0 ou B=0.","x²−7x+12=(x−3)(x−4), logo as raízes são 3 e 4.","Quais são as raízes de x²−5x+6?",["2 e 3","1 e 6","−2 e −3"],0],["Valor máximo","Vértice","Uma parábola com coeficiente a negativo tem concavidade para baixo e o valor da ordenada do vértice é seu máximo.","f(x)=−x²+4x tem máximo 4 em x=2.","Qual é o valor máximo de f(x)=−x²+6x?",["6","9","3"],1]] as typeof highSchoolCatalog["Função quadrática"]));
highSchoolCatalog["Geometria espacial"].push(...([["Área total do cubo","Superfícies","Um cubo possui seis faces quadradas congruentes. Se a aresta mede a, cada face tem área a² e a área total é 6a².","Cubo de aresta 2 cm: área total 6×4=24 cm².","Qual é a área total de um cubo de aresta 3 cm?",["27 cm²","54 cm²","18 cm²"],1],["Volume do cone","Volume","O volume do cone circular reto é V=πr²h/3, um terço do volume do cilindro com mesma base e altura.","Cone de raio 3 e altura 4: V=π×9×4/3=12π.","Qual o volume de um cone de raio 2 e altura 6?",["8π","24π","12π"],0]] as typeof highSchoolCatalog["Geometria espacial"]));
highSchoolCatalog["Matemática financeira"].push(...([["Aumento percentual","Porcentagens","Um aumento de p% transforma um valor V em V×(1+p/100). Para aumento e desconto sucessivos, aplique os fatores em sequência.","R$ 200 com aumento de 15% vira R$ 230.","Um preço de R$ 80 aumenta 25%. Qual o novo preço?",["R$ 90","R$ 100","R$ 105"],1],["Comparação de descontos","Porcentagens","Dois descontos sucessivos não equivalem, em geral, à soma das porcentagens. Cada desconto incide sobre o preço após o desconto anterior.","R$ 100 com descontos de 10% e depois 20% vira R$ 72.","R$ 200 com descontos sucessivos de 10% e 10% custa:",["R$ 160","R$ 162","R$ 180"],1]] as typeof highSchoolCatalog["Matemática financeira"]));
highSchoolCatalog["Conjuntos numéricos"].push(...([["União e interseção","Operações com conjuntos","A união A∪B contém os elementos de A ou de B. A interseção A∩B contém somente os elementos presentes nos dois conjuntos.","Se A={1,2,3} e B={3,4}, A∩B={3}.","Qual é a interseção de {2,4,6} e {4,6,8}?",["{2,8}","{4,6}","{2,4,6,8}"],1]] as typeof highSchoolCatalog["Conjuntos numéricos"]));
