highSchoolCatalog["Progressões PA e PG"].push(...([["Termo geral da PG","Progressões","Em uma progressão geométrica, cada termo é o anterior multiplicado pela razão q. O termo geral é aₙ=a₁qⁿ⁻¹.","Na PG 2,6,18,..., a₄=2×3³=54.","Qual é o quinto termo da PG 1,2,4,8,...?",["16","32","10"],0]] as typeof highSchoolCatalog["Progressões PA e PG"]));
