highSchoolCatalog["Análise combinatória"].push(...([["Combinações simples","Contagem","Em combinações, a ordem não altera o grupo escolhido. Para n objetos distintos tomados k a k, C(n,k)=n!/[k!(n−k)!].","Escolher 2 pessoas entre 4: C(4,2)=6.","Quantas duplas podem ser formadas com 5 pessoas?",["10","20","25"],0]] as typeof highSchoolCatalog["Análise combinatória"]));
