highSchoolCatalog["Razões e proporções"].push(...([["Regra de três inversa","Proporcionalidade","Grandezas inversamente proporcionais variam em sentidos opostos: dobrar uma reduz a outra pela metade, mantendo o produto constante.","4 trabalhadores concluem em 6 dias; 8 trabalhadores, no mesmo ritmo, concluem em 3 dias.","Se 3 máquinas fazem um trabalho em 8 horas, 6 máquinas iguais fazem em:",["16 horas","4 horas","8 horas"],1]] as typeof highSchoolCatalog["Razões e proporções"]));

