highSchoolCatalog["Conjuntos numéricos"].push(...([["Números naturais e sucessores","Naturais e inteiros","Os naturais são usados para contar quantidades e ordenar elementos: 0, 1, 2, 3... Todo natural tem sucessor, obtido somando 1. O zero pertence aos naturais na convenção adotada nesta trilha.","O sucessor de 19 é 20; o antecessor de 19 é 18.","Qual é o sucessor de 99?",["98","100","101"],1],["Inteiros e reta numérica","Naturais e inteiros","O conjunto dos inteiros inclui os naturais, seus opostos negativos e o zero. Na reta numérica, números à direita são maiores. Quanto mais distante à esquerda, menor é o valor.","−7 < −2 < 0 < 4; portanto −2 é maior que −7.","Qual inteiro é maior?",["−8","−3","−10"],1],["Módulo e oposto","Naturais e inteiros","O módulo |a| mede a distância de a até zero e nunca é negativo. O oposto de a é −a; somar um número ao seu oposto resulta em zero.","|−9|=9 e o oposto de −9 é 9.","Quanto é |−12|?",["−12","12","0"],1],["Frações equivalentes","Racionais","Números racionais podem ser escritos como a/b, com a e b inteiros e b diferente de zero. Multiplicar numerador e denominador pelo mesmo número não nulo produz fração equivalente.","2/3 = 4/6 = 6/9.","Qual fração equivale a 3/4?",["6/8","3/8","4/3"],0],["Dízimas periódicas","Racionais","Decimais finitos ou infinitos periódicos representam racionais. Uma dízima periódica repete um bloco de algarismos. O decimal 0,333... é igual a 1/3.","0,666... = 2/3.","Qual fração representa 0,111...?",["1/9","1/10","1/11"],0],["Irracionais e raízes","Reais e irracionais","Irracionais não podem ser expressos como razão entre dois inteiros; suas representações decimais são infinitas e não periódicas. Exemplos incluem √2 e π. A raiz de um quadrado perfeito, como √49, é racional.","√3 é irracional, mas √64=8 é racional.","Qual número é racional?",["√5","π","√81"],2],["Inclusão de conjuntos","Reais e irracionais","Os naturais estão contidos nos inteiros, que estão contidos nos racionais, que por sua vez estão contidos nos reais: ℕ⊂ℤ⊂ℚ⊂ℝ. Irracionais também são reais, mas não racionais.","−4 pertence a ℤ, ℚ e ℝ, mas não a ℕ.","A qual conjunto pertence necessariamente todo inteiro?",["Racionais","Irracionais","Somente naturais"],0],["Intervalos abertos e fechados","Intervalos e aplicações","Um intervalo fechado inclui os extremos, indicado por colchetes; um intervalo aberto exclui os extremos, indicado por parênteses. [2,5] contém 2 e 5; (2,5) não contém nenhum dos dois.","3 pertence a (2,5), enquanto 2 não pertence.","Qual número pertence ao intervalo (−1,2)?",["−1","0","2"],1],["União e interseção","Intervalos e aplicações","A união A∪B reúne elementos que pertencem a pelo menos um dos conjuntos. A interseção A∩B contém apenas elementos comuns aos dois. Essas operações ajudam a descrever soluções de problemas.","A={1,2,3}, B={3,4}; A∩B={3} e A∪B={1,2,3,4}.","Qual é a interseção de {2,4,6} e {4,6,8}?",["{2,8}","{4,6}","{2,4,6,8}"],1]] as typeof highSchoolCatalog["Conjuntos numéricos"]));
highSchoolCatalog["Potenciação e radiciação"].push(...([["Potências com expoente zero","Potências e propriedades","Para toda base não nula a, a⁰=1. Essa propriedade decorre de aᵐ/aᵐ=a⁰ e do fato de um número não nulo dividido por ele mesmo ser 1.","7⁰=1 e (−3)⁰=1.","Quanto vale 12⁰?",["0","1","12"],1],["Produto de potências da mesma base","Potências e propriedades","Ao multiplicar potências de mesma base, conservamos a base e somamos os expoentes: aᵐ·aⁿ=aᵐ⁺ⁿ. A regra não vale para bases diferentes sem transformações adicionais.","2³·2⁴=2⁷=128.","Quanto é 3²·3³?",["3⁵","3⁶","9⁵"],0],["Quociente de potências","Potências e propriedades","Na divisão de potências com a mesma base não nula, subtraímos os expoentes: aᵐ/aⁿ=aᵐ⁻ⁿ. A regra é útil para simplificar expressões.","5⁶/5²=5⁴=625.","Qual é a forma simplificada de 2⁷/2³?",["2¹⁰","2⁴","2³"],1],["Potência de potência","Potências e propriedades","Quando uma potência é elevada a outra potência, multiplicamos os expoentes: (aᵐ)ⁿ=aᵐⁿ. Os parênteses são importantes para distinguir (−2)² de −2².","(3²)³=3⁶=729.","Qual expressão equivale a (2³)²?",["2⁵","2⁶","2⁹"],1],["Expoentes negativos","Potências e propriedades","Expoente inteiro negativo indica inverso multiplicativo: a⁻ⁿ=1/aⁿ, para a diferente de zero. Assim, expoente negativo não torna o resultado necessariamente negativo.","2⁻³=1/8.","Quanto vale 5⁻²?",["−25","1/25","25"],1],["Raiz cúbica e índices","Radicais","A raiz n-ésima de um número é o valor que elevado a n produz o radicando. Raízes de índice ímpar admitem radicandos negativos nos reais; raízes quadradas reais exigem radicando não negativo.","∛(−27)=−3, pois (−3)³=−27.","Quanto é ∛125?",["5","25","15"],0],["Operações com radicais semelhantes","Radicais","Radicais com mesmo índice e mesmo radicando podem ser somados pelos coeficientes. Antes de somar, simplifique cada radical para identificar termos semelhantes.","2√3+5√3=7√3.","Quanto vale 4√2−√2?",["3√2","3","4"],0],["Racionalização simples","Radicais","Racionalizar é reescrever uma fração sem radical no denominador. Para 1/√a, com a positivo, multiplique numerador e denominador por √a.","1/√5=√5/5.","Qual expressão equivale a 1/√3?",["√3/3","3√3","√3"],0]] as typeof highSchoolCatalog["Potenciação e radiciação"]));
highSchoolCatalog["Produtos notáveis e fatoração"].push(...([["Quadrado da soma","Identidades algébricas","O quadrado de uma soma possui três parcelas: (a+b)²=a²+2ab+b². O termo 2ab é indispensável, pois a expressão representa (a+b)(a+b).","(x+4)²=x²+8x+16.","Qual é o termo do meio em (x+5)²?",["5x","10x","25x"],1],["Quadrado da diferença","Identidades algébricas","No quadrado da diferença, (a−b)²=a²−2ab+b². O último termo é positivo porque o produto de dois números negativos é positivo.","(x−3)²=x²−6x+9.","Qual é a expansão de (x−2)²?",["x²−4","x²−4x+4","x²+4x+4"],1],["Produto da soma pela diferença","Identidades algébricas","Multiplicar (a+b)(a−b) elimina os termos mistos e produz a²−b². Essa identidade também pode ser usada no sentido inverso para fatorar.","(x+7)(x−7)=x²−49.","Quanto vale (y+5)(y−5)?",["y²−25","y²+25","y²−10y+25"],0],["Fator comum em evidência","Fatoração","Fatorar por fator comum consiste em identificar um número ou variável presente em todos os termos e colocá-lo em evidência. A distributiva permite verificar o resultado.","6x+9=3(2x+3).","Qual é a fatoração de 8x+12?",["4(2x+3)","2(4x+12)","8(x+12)"],0],["Fatoração por agrupamento","Fatoração","Em expressões de quatro termos, agrupe parcelas para obter um fator binomial comum. Depois coloque esse binômio em evidência.","ax+ay+bx+by=a(x+y)+b(x+y)=(a+b)(x+y).","Qual é a fatoração de x²+2x+3x+6?",["(x+2)(x+3)","(x+6)(x+1)","x(x+5)+6"],0],["Trinômio quadrado perfeito","Fatoração","Um trinômio é quadrado perfeito quando pode ser escrito como a²±2ab+b². Identifique os quadrados extremos e confirme se o termo central é o dobro do produto das raízes.","x²+10x+25=(x+5)².","Qual é a fatoração de x²−8x+16?",["(x−8)²","(x−4)²","(x+4)²"],1],["Trinômio de segundo grau","Fatoração","Quando um trinômio monômio em x² tem raízes r₁ e r₂, ele pode ser escrito como (x−r₁)(x−r₂). Para x²+bx+c, procure dois números cuja soma seja b e produto seja c.","x²−5x+6=(x−2)(x−3).","Qual é a fatoração de x²+5x+6?",["(x+2)(x+3)","(x+1)(x+6)","(x−2)(x−3)"],0]] as typeof highSchoolCatalog["Produtos notáveis e fatoração"]));
highSchoolCatalog["Equações e inequações"].push(...([["Equações de primeiro grau","Equações","Uma equação do primeiro grau pode ser escrita como ax+b=0, com a diferente de zero. Para isolarmos x, realizamos operações equivalentes nos dois membros da igualdade.","5x−10=0 → 5x=10 → x=2.","Resolva 4x+8=0.",["−2","2","−8"],0],["Equações com parênteses","Equações","Use a distributiva para eliminar parênteses antes de reunir termos semelhantes. Depois isole a incógnita, mantendo a igualdade a cada transformação.","2(x+3)=14 → 2x+6=14 → x=4.","Resolva 3(x−2)=9.",["3","5","7"],1],["Equações com frações","Equações","Quando há denominadores numéricos não nulos, multiplique ambos os membros pelo mínimo múltiplo comum dos denominadores. Isso remove frações sem alterar a solução.","x/3+1=5 → x/3=4 → x=12.","Resolva x/4=3.",["7","12","16"],1],["Equações do segundo grau","Equações quadráticas","Uma equação quadrática tem forma ax²+bx+c=0, a≠0. Suas raízes podem ser obtidas por fatoração, completamento de quadrados ou fórmula resolutiva.","x²−5x+6=0 → (x−2)(x−3)=0 → x=2 ou x=3.","Quais são as raízes de x²−9=0?",["−3 e 3","0 e 3","3 e 9"],0],["Discriminante e número de raízes","Equações quadráticas","Na fórmula de Bhaskara, Δ=b²−4ac. Se Δ>0, há duas raízes reais distintas; se Δ=0, uma raiz real dupla; se Δ<0, não há raízes reais.","Para x²−4x+4=0, Δ=16−16=0.","Se Δ<0, quantas raízes reais a equação possui?",["Duas","Uma","Nenhuma"],2],["Inequações de primeiro grau","Inequações","Inequações comparam expressões usando <, >, ≤ ou ≥. Some ou subtraia o mesmo valor em ambos os lados sem mudar o sinal. Ao multiplicar por número negativo, inverta o sentido.","2x+1<7 → 2x<6 → x<3.","Resolva x+5≥9.",["x≥4","x≤4","x>14"],0],["Sistemas de inequações","Inequações","Para satisfazer simultaneamente duas inequações, encontre a interseção dos conjuntos solução. Represente a resposta em intervalo e na reta real.","x>1 e x≤4 → 1<x≤4.","Qual número satisfaz x>2 e x<5?",["2","4","5"],1],["Inequação produto","Inequações","Para resolver (x−a)(x−b)>0, localize os zeros dos fatores e analise os sinais em cada intervalo. Um produto é positivo quando os fatores têm o mesmo sinal.","(x−1)(x−3)>0 → x<1 ou x>3.","Qual valor satisfaz (x−2)(x−5)>0?",["3","4","6"],2]] as typeof highSchoolCatalog["Equações e inequações"]));

// Ampliação do primeiro ano: funções e proporcionalidade.
highSchoolCatalog["Função afim"].push(...([["Plano cartesiano e pares ordenados","Fundamentos","Uma função associa a cada entrada x do domínio exatamente uma saída y. No plano cartesiano, representamos cada associação por um ponto (x,y). O eixo horizontal é x e o vertical é y.","Para f(x)=x+2, os pontos (0,2), (1,3) e (2,4) pertencem ao gráfico.","Qual ponto pertence a f(x)=x+3?",["(2,5)","(2,3)","(3,2)"],0],["Coeficiente angular","Fundamentos","Na função afim f(x)=ax+b, o coeficiente a indica quanto y varia quando x aumenta uma unidade. Se a>0, a reta é crescente; se a<0, é decrescente; se a=0, é constante.","Em f(x)=−2x+5, a=−2, portanto a reta é decrescente.","A função f(x)=4x−1 é:",["Decrescente","Crescente","Constante"],1],["Coeficiente linear","Fundamentos","O coeficiente b de f(x)=ax+b é o valor de f(0), isto é, onde a reta intercepta o eixo vertical. Para encontrá-lo, substitua x por zero.","Em f(x)=3x−7, f(0)=−7.","Onde f(x)=2x+6 corta o eixo y?",["2","6","−6"],1],["Raiz da função afim","Zeros e gráficos","A raiz ou zero de uma função é o valor de x que torna f(x)=0. Para ax+b=0, com a≠0, a raiz é x=−b/a. No gráfico, é o ponto em que a reta cruza o eixo x.","f(x)=2x−8 → 2x−8=0 → x=4.","Qual é a raiz de f(x)=3x−12?",["3","4","12"],1],["Construção do gráfico","Zeros e gráficos","O gráfico de uma função afim é uma reta. Para desenhá-la, calcule dois pares ordenados distintos, marque-os no plano e trace a reta que passa pelos pontos.","Para f(x)=x−1, podemos marcar (0,−1) e (2,1).","Qual ponto pertence a f(x)=2x−3?",["(2,1)","(2,3)","(1,1)"],0],["Taxa de variação entre pontos","Zeros e gráficos","Conhecendo dois pontos (x₁,y₁) e (x₂,y₂), com x₁≠x₂, calculamos o coeficiente angular por a=(y₂−y₁)/(x₂−x₁). A taxa mede a variação de saída por unidade de entrada.","Entre (1,3) e (3,7), a=(7−3)/(3−1)=2.","Qual é a inclinação entre (0,1) e (2,7)?",["2","3","6"],1],["Determinação da lei da função","Modelagem","Para descobrir f(x)=ax+b a partir de dois pontos, calcule a pela taxa de variação e substitua um ponto na expressão para encontrar b.","Se f(0)=2 e f(3)=11, então b=2, a=(11−2)/3=3 e f(x)=3x+2.","Se f(0)=4 e f(2)=10, qual é f(x)?",["3x+4","2x+4","3x+2"],0],["Função afim no cotidiano","Modelagem","Situações com parcela fixa e valor por unidade podem ser descritas por uma função afim. Identifique o custo inicial b e o acréscimo por unidade a, respeitando as unidades.","Táxi cobra R$ 6 de bandeirada e R$ 3 por km: C(x)=3x+6.","Qual o custo de 5 km nessa corrida?",["R$ 15","R$ 21","R$ 30"],1],["Interseção entre duas retas","Modelagem","Para descobrir onde duas funções afins têm o mesmo valor, iguale suas leis e resolva a equação resultante. O x encontrado representa a abscissa do ponto de encontro.","2x+1=x+5 → x=4; ambas valem 9.","Para f(x)=3x e g(x)=x+8, em qual x elas se encontram?",["2","4","8"],1]] as typeof highSchoolCatalog["Função afim"]));
highSchoolCatalog["Função quadrática"].push(...([["Coeficientes da função quadrática","Fundamentos","A função quadrática tem forma f(x)=ax²+bx+c, com a≠0. O sinal de a determina a concavidade: para cima quando a>0 e para baixo quando a<0.","Em f(x)=−2x²+3x+1, a=−2 e a parábola é voltada para baixo.","Qual função tem concavidade para cima?",["−x²+1","2x²−3","−3x²"],1],["Valor numérico de uma função quadrática","Fundamentos","Para calcular f(k), substitua x por k em todos os termos e respeite a ordem das operações, especialmente potências e sinais.","f(x)=x²−2x+1 → f(3)=9−6+1=4.","Se f(x)=x²+2x, quanto é f(2)?",["6","8","10"],1],["Raízes por fatoração","Raízes e discriminante","As raízes são os valores de x para os quais f(x)=0. Se o polinômio puder ser fatorado, use a propriedade do produto nulo: se AB=0, então A=0 ou B=0.","x²−7x+12=(x−3)(x−4), logo as raízes são 3 e 4.","Quais são as raízes de x²−5x+6?",["1 e 6","2 e 3","−2 e −3"],1],["Fórmula resolutiva de Bhaskara","Raízes e discriminante","Para ax²+bx+c=0, com a≠0, calcule Δ=b²−4ac e use x=(−b±√Δ)/(2a). Quando Δ≥0, essa expressão fornece as raízes reais.","x²−4x+3=0: Δ=16−12=4; x=(4±2)/2, portanto x=1 ou 3.","Quais são as raízes de x²−6x+8=0?",["2 e 4","−2 e −4","1 e 8"],0],["Discriminante e interseções com eixo x","Raízes e discriminante","O discriminante Δ indica o número de zeros reais: Δ>0 gera duas interseções distintas com o eixo x; Δ=0, uma interseção tangente; Δ<0, nenhuma interseção real.","Para x²+1=0, Δ=−4 e não existem raízes reais.","Se Δ=0, o gráfico toca o eixo x em quantos pontos?",["Zero","Um","Dois"],1],["Vértice da parábola","Vértice e gráfico","O vértice é o ponto de mínimo ou máximo da parábola. Sua abscissa é xᵥ=−b/(2a) e sua ordenada é yᵥ=f(xᵥ).","f(x)=x²−4x+1 → xᵥ=2 e yᵥ=−3.","Qual é o x do vértice de f(x)=x²−6x+2?",["2","3","6"],1],["Máximo e mínimo","Vértice e gráfico","Se a>0, o vértice representa o valor mínimo da função; se a<0, representa o máximo. Isso permite otimizar áreas, receitas e outras grandezas.","f(x)=−x²+4x tem máximo em x=2, com valor 4.","Qual é o valor máximo de f(x)=−x²+6x?",["6","9","12"],1],["Eixo de simetria","Vértice e gráfico","A parábola é simétrica em relação à reta vertical x=xᵥ. Pontos equidistantes dessa reta têm a mesma ordenada.","Em f(x)=x²−4x, o eixo é x=2; f(1)=f(3)=−3.","Qual é o eixo de simetria de f(x)=x²−8x+1?",["x=8","x=4","x=−4"],1],["Sinal da função quadrática","Aplicações","O sinal de f(x) pode ser estudado pelas raízes e pela concavidade. Quando a>0 e há duas raízes distintas, a função é negativa entre elas e positiva fora delas.","f(x)=(x−1)(x−4) é negativa para 1<x<4.","Qual valor torna (x−2)(x−6) negativo?",["1","4","7"],1],["Problemas de área com parábolas","Aplicações","Uma função quadrática pode modelar a área de um retângulo quando a soma de duas dimensões é fixa. Escreva a área em função de uma dimensão e use o vértice para encontrar o máximo.","Com perímetro 20, lados x e 10−x, área A(x)=x(10−x), máxima em x=5.","Qual é a área máxima de um retângulo de perímetro 20?",["20","25","50"],1]] as typeof highSchoolCatalog["Função quadrática"]));
highSchoolCatalog["Razões e proporções"].push(...([["Razão entre grandezas","Razões","Uma razão a/b compara duas quantidades da mesma natureza ou grandezas distintas, desde que b≠0. Quando as unidades são iguais, simplifique a razão para comparar valores.","Em uma turma com 12 meninas e 8 meninos, a razão meninas:meninos é 12/8=3/2.","Qual é a razão simplificada de 15 para 20?",["3/4","4/3","5/4"],0],["Proporções e produto cruzado","Razões","Uma proporção é a igualdade entre duas razões a/b=c/d, com b,d≠0. Pela propriedade fundamental, ad=bc, o que permite encontrar um termo desconhecido.","x/4=3/2 → 2x=12 → x=6.","Se x/5=2/3, quanto vale x?",["10/3","5/6","15/2"],0],["Grandezas diretamente proporcionais","Proporcionalidade","Duas grandezas são diretamente proporcionais quando a razão entre seus valores correspondentes permanece constante. Se uma dobra, a outra também dobra, mantidas as condições.","3 metros de tecido custam R$ 24; 6 metros custam R$ 48.","Se 4 kg custam R$ 28, quanto custam 7 kg?",["R$ 35","R$ 49","R$ 56"],1],["Grandezas inversamente proporcionais","Proporcionalidade","Grandezas inversamente proporcionais mantêm constante o produto de seus valores. Se uma dobra, a outra cai pela metade, desde que as demais condições permaneçam iguais.","2 máquinas levam 12 horas; 4 máquinas iguais levam 6 horas.","Se 5 pessoas fazem um serviço em 8 dias, 10 pessoas no mesmo ritmo levam:",["4 dias","8 dias","16 dias"],0],["Regra de três simples direta","Regra de três","Na regra de três direta, monte duas razões equivalentes com unidades alinhadas e resolva a proporção. Verifique se aumentar uma grandeza realmente aumenta a outra.","4 litros custam R$ 18; 10 litros custam x. 4/10=18/x → x=45.","Se 6 ingressos custam R$ 90, 4 ingressos custam:",["R$ 45","R$ 60","R$ 75"],1],["Regra de três simples inversa","Regra de três","Na regra de três inversa, multiplique valores correspondentes das duas grandezas. Esse procedimento se aplica quando uma cresce na mesma proporção em que a outra diminui.","3 torneiras enchem um reservatório em 8 horas; 6 torneiras iguais, em 4 horas.","Se 4 operários levam 9 dias, 6 operários iguais levam:",["6 dias","12 dias","13,5 dias"],0],["Regra de três composta","Regra de três","Na regra de três composta, compare a incógnita com cada uma das demais grandezas, identificando relações diretas e inversas. Monte o produto de fatores e confira o sentido do resultado.","2 máquinas fazem 40 peças em 5 horas; 4 máquinas no mesmo ritmo fazem 80 peças em 5 horas.","Se 3 máquinas produzem 60 peças em 4 horas, 6 máquinas produzem em 4 horas:",["90","120","180"],1],["Escalas cartográficas","Escalas e aplicações","Escala é a razão entre uma distância no desenho e a correspondente distância real, usando a mesma unidade. Na escala 1:100000, 1 cm no mapa representa 100000 cm, ou 1 km, na realidade.","Na escala 1:50000, 2 cm no mapa representam 1 km real.","Na escala 1:100000, 3 cm representam:",["300 m","3 km","30 km"],1],["Divisão proporcional","Escalas e aplicações","Para dividir um total em partes diretamente proporcionais a pesos, some os pesos e multiplique o total pela fração correspondente a cada um.","Dividir R$ 120 na razão 2:3: a primeira parte é 120×2/5=48 e a segunda é 72.","Ao dividir R$ 200 na razão 1:3, qual é a menor parte?",["R$ 50","R$ 75","R$ 100"],0],["Densidade e velocidade média","Escalas e aplicações","Razões entre grandezas diferentes originam taxas como densidade (massa/volume) e velocidade média (distância/tempo). É essencial indicar as unidades para interpretar o resultado.","Um carro percorre 180 km em 3 horas: velocidade média de 60 km/h.","Qual é a velocidade média de 240 km em 4 horas?",["40 km/h","60 km/h","80 km/h"],1]] as typeof highSchoolCatalog["Razões e proporções"]));

// Segundo ano, primeira etapa: exponenciais, progressões, trigonometria e matrizes.
highSchoolCatalog["Funções exponenciais e logarítmicas"].push(...([["Potências de base positiva","Fundamentos exponenciais","A função exponencial tem forma f(x)=aˣ, com a>0 e a≠1. Para a>1 ela é crescente; para 0<a<1 é decrescente. Seus valores são sempre positivos.","f(x)=2ˣ: f(0)=1, f(1)=2 e f(3)=8.","Quanto vale 3⁰?",["0","1","3"],1],["Crescimento exponencial","Fundamentos exponenciais","Quando uma quantidade cresce por um percentual fixo a cada período, multiplicamos pelo mesmo fator repetidamente. O modelo é Q(t)=Q₀(1+r)ᵗ, com r escrito em decimal.","100 unidades com crescimento de 20% por 2 períodos: 100×1,2²=144.","Uma população de 200 cresce 10% em um período. Qual o novo total?",["210","220","240"],1],["Decaimento exponencial","Fundamentos exponenciais","No decaimento percentual constante, cada período preserva uma fração da quantidade anterior. Se a queda é de 25%, o fator multiplicativo é 0,75.","80 unidades após uma queda de 25%: 80×0,75=60.","Uma amostra de 120 unidades perde 50% em um período. Restam:",["30","60","90"],1],["Equações exponenciais com mesma base","Equações exponenciais","Se a>0 e a≠1, a igualdade aᵐ=aⁿ implica m=n. Reescreva os dois lados com a mesma base antes de comparar expoentes.","2ˣ=16=2⁴, então x=4.","Se 3ˣ=81, qual é x?",["3","4","9"],1],["Equações exponenciais por substituição","Equações exponenciais","Em equações com a²ˣ e aˣ, use y=aˣ, com y>0, para transformar a expressão em equação quadrática. Depois descarte valores de y não positivos.","4ˣ−5·2ˣ+4=0 → y²−5y+4=0 → y=1 ou 4 → x=0 ou 2.","Se 2²ˣ=16, qual é x?",["2","4","8"],0],["Definição de logaritmo","Logaritmos","O logaritmo logₐb é o expoente ao qual elevamos a base a para obter b. Exige a>0, a≠1 e b>0. A equivalência fundamental é logₐb=x ⇔ aˣ=b.","log₂32=5 porque 2⁵=32.","Quanto é log₃27?",["2","3","9"],1],["Logaritmo do quociente","Logaritmos","Para x,y>0, logₐ(x/y)=logₐx−logₐy. Essa propriedade transforma divisões em subtrações, preservadas as condições de existência.","log₁₀(1000/10)=3−1=2.","Quanto é log₁₀(100/10)?",["1","2","10"],0],["Logaritmo da potência","Logaritmos","Para x>0, logₐ(xⁿ)=n·logₐx. O expoente passa a multiplicar o logaritmo, o que ajuda a simplificar expressões e resolver equações.","log₂(8²)=2·log₂8=6.","Quanto vale log₂(4³)?",["5","6","8"],1],["Mudança de base","Logaritmos","Para bases válidas a e b, logₐx=log_bx/log_ba. Essa relação permite calcular logaritmos em uma base usando outra conhecida.","log₂8=log₁₀8/log₁₀2=3.","Quanto vale log₄16?",["2","4","8"],0],["Equações logarítmicas","Aplicações","Para resolver logₐf(x)=c, escreva f(x)=aᶜ e confira se f(x)>0. A condição de existência deve ser verificada ao final.","log₂(x−1)=3 → x−1=8 → x=9, válido.","Resolva log₃(x+2)=2.",["7","9","11"],0]] as typeof highSchoolCatalog["Funções exponenciais e logarítmicas"]));
highSchoolCatalog["Progressões PA e PG"].push(...([["Identificando uma PA","Progressão aritmética","Uma progressão aritmética é uma sequência em que a diferença entre termos consecutivos é constante, chamada razão r. A razão pode ser positiva, negativa ou zero.","Na PA 5,9,13,17, a razão é 4.","Qual a razão da PA 12,9,6,3?",["−3","3","−6"],0],["Termo geral da PA","Progressão aritmética","O termo de posição n em uma PA é aₙ=a₁+(n−1)r. Use essa fórmula para encontrar posições distantes sem listar todos os termos.","PA com a₁=2 e r=3: a₅=2+4×3=14.","Na PA 4,7,10,..., qual é o sexto termo?",["16","19","22"],1],["Soma dos termos da PA","Progressão aritmética","A soma dos n primeiros termos de uma PA é Sₙ=n(a₁+aₙ)/2. O método funciona porque pares de termos equidistantes dos extremos têm soma constante.","1+2+3+4+5=5(1+5)/2=15.","Qual é a soma de 1 a 10?",["45","55","65"],1],["PA decrescente","Progressão aritmética","Se a razão da PA é negativa, os termos diminuem em passos iguais. A fórmula do termo geral permanece válida.","Na PA 20,16,12,8,..., r=−4 e a₅=4.","Qual é o próximo termo de 15,10,5,0,...?",["−5","5","−10"],0],["Identificando uma PG","Progressão geométrica","Em uma progressão geométrica, cada termo é obtido multiplicando o anterior por uma razão q constante. Para termos não nulos, q é o quociente entre termos consecutivos.","Na PG 3,6,12,24, a razão é 2.","Qual a razão da PG 2,10,50,...?",["2","5","10"],1],["Termo geral da PG","Progressão geométrica","O termo geral da PG é aₙ=a₁qⁿ⁻¹. A fórmula permite calcular qualquer posição diretamente, desde que a₁ e q sejam conhecidos.","Na PG 2,6,18,..., a₄=2×3³=54.","Qual o quinto termo da PG 1,3,9,...?",["27","81","243"],1],["Soma finita da PG","Progressão geométrica","Para q≠1, a soma dos n primeiros termos de uma PG é Sₙ=a₁(qⁿ−1)/(q−1). Se q=1, a soma é n·a₁.","PG 1,2,4,8: S₄=1(2⁴−1)/(2−1)=15.","Qual a soma dos quatro primeiros termos de 2,4,8,16,...?",["28","30","32"],1],["Soma de PG infinita","Progressão geométrica","Se |q|<1, os termos da PG tendem a zero e a soma infinita converge para S=a₁/(1−q). Para |q|≥1, essa fórmula não representa soma convergente em geral.","1+1/2+1/4+...=1/(1−1/2)=2.","Quanto vale 3+1,5+0,75+...?",["4,5","6","9"],1],["Interpolação aritmética","Aplicações de progressões","Interpolar meios aritméticos é inserir termos para formar uma PA entre dois valores. Calcule a razão dividindo a diferença entre extremos pelo número de intervalos.","Entre 2 e 14, inserindo 2 meios: 2,6,10,14, com r=4.","Qual número fica entre 4 e 10 em uma PA de três termos?",["6","7","8"],1],["Progressões em situações reais","Aplicações de progressões","A PA modela acréscimos absolutos constantes; a PG modela multiplicações constantes. Identificar o padrão é essencial para escolher a fórmula correta.","Depósito de R$ 100, depois R$ 150, R$ 200: PA de razão 50.","Uma população que dobra a cada ano segue qual padrão?",["PA de razão 2","PG de razão 2","PA de razão 1"],1]] as typeof highSchoolCatalog["Progressões PA e PG"]));
highSchoolCatalog["Trigonometria"].push(...([["Identificação dos catetos","Triângulo retângulo","Em um triângulo retângulo, a hipotenusa é o lado oposto ao ângulo de 90°. Para um ângulo agudo escolhido, o cateto oposto fica à sua frente e o adjacente toca o ângulo.","Num triângulo 3-4-5, a hipotenusa mede 5.","Qual é a hipotenusa de um triângulo com catetos 6 e 8?",["10","12","14"],0],["Seno no triângulo retângulo","Razões trigonométricas","O seno de um ângulo agudo é a razão entre o cateto oposto e a hipotenusa. Essa razão independe do tamanho do triângulo quando o ângulo é mantido.","Oposto=5 e hipotenusa=13: sen θ=5/13.","Se o oposto mede 3 e a hipotenusa 5, sen θ é:",["3/5","5/3","4/5"],0],["Cosseno no triângulo retângulo","Razões trigonométricas","O cosseno de um ângulo agudo é o cateto adjacente dividido pela hipotenusa. Identifique o ângulo antes de escolher o cateto adjacente.","Adjacente=12 e hipotenusa=13: cos θ=12/13.","Se adjacente=4 e hipotenusa=5, cos θ é:",["3/5","4/5","5/4"],1],["Tangente no triângulo retângulo","Razões trigonométricas","A tangente de um ângulo agudo é o cateto oposto dividido pelo cateto adjacente. Também vale tg θ=sen θ/cos θ quando cos θ≠0.","Oposto=6 e adjacente=8: tg θ=3/4.","Se oposto=9 e adjacente=3, tg θ é:",["1/3","3","6"],1],["Ângulos de 30, 45 e 60 graus","Ângulos notáveis","Os valores trigonométricos notáveis são sen30°=1/2, cos30°=√3/2, sen45°=cos45°=√2/2 e sen60°=√3/2. Eles aparecem em triângulos especiais.","cos60°=1/2 e tg45°=1.","Quanto vale cos60°?",["1/2","√2/2","√3/2"],0],["Graus e radianos","Círculo trigonométrico","Uma volta completa mede 360° ou 2π radianos. Para converter graus em radianos, multiplique por π/180; para converter radianos em graus, multiplique por 180/π.","180°=π rad e 90°=π/2 rad.","Quanto é 60° em radianos?",["π/6","π/3","2π/3"],1],["Sinais por quadrante","Círculo trigonométrico","No círculo trigonométrico, o cosseno é a coordenada horizontal e o seno é a vertical. No segundo quadrante, seno é positivo e cosseno negativo.","Em 120°, sen120°>0 e cos120°<0.","Qual razão é negativa no segundo quadrante?",["Seno","Cosseno","Ambas"],1],["Relação fundamental","Círculo trigonométrico","Para todo ângulo real θ, sen²θ+cos²θ=1. Essa identidade decorre da equação do círculo unitário x²+y²=1.","Se senθ=3/5 e θ é agudo, cosθ=4/5.","Se senθ=0 e cosθ>0, cosθ vale:",["0","1","−1"],1],["Lei dos senos","Triângulos quaisquer","Em qualquer triângulo, a/sen A=b/sen B=c/sen C, onde cada lado é oposto ao ângulo correspondente. A lei dos senos ajuda quando conhecemos lados e ângulos opostos.","Se a=6 e senA=1/2, então a/senA=12.","Se a/senA=10 e senB=1/2, quanto vale b?",["5","10","20"],0],["Lei dos cossenos","Triângulos quaisquer","Para um triângulo com lados a,b,c e ângulo A oposto ao lado a, vale a²=b²+c²−2bc·cos A. Essa relação generaliza Pitágoras.","Se b=3,c=4,A=90°, então a²=9+16=25 e a=5.","Se b=5,c=5 e A=60°, quanto vale a?",["5","10","√50"],0]] as typeof highSchoolCatalog["Trigonometria"]));
highSchoolCatalog["Matrizes e determinantes"].push(...([["Ordem de uma matriz","Matrizes","Uma matriz m×n possui m linhas e n colunas. O elemento aᵢⱼ está na linha i e coluna j. A ordem é importante para saber quais operações são possíveis.","Uma matriz com 2 linhas e 3 colunas tem ordem 2×3.","Uma matriz de 4 linhas e 2 colunas tem ordem:",["2×4","4×2","4×4"],1],["Matriz identidade","Matrizes","A matriz identidade Iₙ é quadrada, possui 1 na diagonal principal e 0 nas demais posições. Multiplicar uma matriz compatível pela identidade preserva seus elementos.","I₂=[[1,0],[0,1]].","Qual elemento fica na diagonal principal de I₃?",["0","1","3"],1],["Adição de matrizes","Operações matriciais","Somamos matrizes de mesma ordem elemento a elemento. Matrizes de ordens diferentes não podem ser somadas diretamente.","[[1,2],[3,4]]+[[2,1],[0,5]]=[[3,3],[3,9]].","Qual é o elemento superior esquerdo da soma [[1,0],[0,1]]+[[3,2],[1,4]]?",["3","4","5"],1],["Multiplicação por escalar","Operações matriciais","Multiplicar uma matriz por um escalar significa multiplicar todos os elementos pelo mesmo número. A ordem da matriz não muda.","3·[[1,−2],[0,4]]=[[3,−6],[0,12]].","Quanto é o elemento 2,1 de 2·[[1,2],[3,4]]?",["3","6","8"],1],["Produto de matrizes","Operações matriciais","O produto AB existe quando o número de colunas de A é igual ao número de linhas de B. Cada elemento do produto é a soma dos produtos correspondentes de uma linha por uma coluna.","[[1,2]]·[[3],[4]]=[[11]].","Quanto vale [[2,1]]·[[3],[5]]?",["8","11","15"],1],["Determinante de matriz 2 por 2","Determinantes","Para A=[[a,b],[c,d]], o determinante é ad−bc. Determinante zero indica que a matriz quadrada não possui inversa.","det([[2,3],[1,4]])=8−3=5.","Qual o determinante de [[3,2],[1,5]]?",["13","17","15"],0],["Determinante de matriz 3 por 3","Determinantes","O determinante de uma matriz 3×3 pode ser calculado por expansão de cofatores ou regra de Sarrus. Em matriz triangular, basta multiplicar os elementos da diagonal principal.","det([[2,1,0],[0,3,4],[0,0,5]])=2×3×5=30.","Qual o determinante da matriz diagonal com 2,4,3 na diagonal?",["9","24","12"],1],["Matriz inversa 2 por 2","Determinantes","Uma matriz quadrada 2×2 com determinante não nulo possui inversa. Para A=[[a,b],[c,d]], A⁻¹=(1/(ad−bc))[[d,−b],[−c,a]].","A=[[2,0],[0,3]] tem inversa [[1/2,0],[0,1/3]].","Qual condição garante inversa de uma matriz 2×2?",["Determinante igual a zero","Determinante diferente de zero","Elementos positivos"],1],["Sistemas por matrizes","Aplicações","Um sistema linear pode ser representado por AX=B. Se A é inversível, a solução é X=A⁻¹B. Essa notação organiza equações e facilita métodos computacionais.","x+y=5 e x−y=1 podem ser escritos [[1,1],[1,−1]][[x],[y]]=[[5],[1]].","Na escrita AX=B, o vetor X representa:",["Incógnitas","Coeficientes","Termos independentes"],0]] as typeof highSchoolCatalog["Matrizes e determinantes"]));

// Segundo ano, segunda etapa: sistemas, combinatória, probabilidade e sólidos.
highSchoolCatalog["Sistemas lineares"].push(...([["Equações com duas incógnitas","Conceitos iniciais","Uma equação linear em x e y tem forma ax+by=c. Em geral, uma única equação admite vários pares solução; um sistema combina condições que devem ser atendidas simultaneamente.","x+y=5 admite (1,4), (2,3) e (5,0).","Qual par satisfaz x+y=7?",["(2,5)","(2,4)","(3,5)"],0],["Método da substituição","Métodos de resolução","Isole uma incógnita em uma equação e substitua a expressão obtida na outra. Resolva a equação resultante e retorne para encontrar a segunda incógnita.","x+y=9 e x−y=1: x=9−y; 9−2y=1; y=4, x=5.","Se x+y=8 e x−y=2, quanto vale y?",["2","3","5"],1],["Método da adição","Métodos de resolução","Some as equações depois de multiplicar uma ou ambas por fatores convenientes, de modo que os coeficientes de uma incógnita se anulem.","2x+y=11 e x−y=1 → 3x=12 → x=4 e y=3.","Se x+y=12 e x−y=4, qual é x?",["4","8","12"],1],["Classificação de sistemas","Classificação","Um sistema pode ser possível e determinado (uma solução), possível e indeterminado (infinitas soluções) ou impossível (nenhuma solução). A classificação depende da compatibilidade das equações.","x+y=2 e 2x+2y=4 possuem infinitas soluções.","O sistema x+y=2 e x+y=5 é:",["Possível determinado","Possível indeterminado","Impossível"],2],["Interpretação gráfica","Classificação","Cada equação linear com duas incógnitas representa uma reta. Retas concorrentes indicam solução única, coincidentes indicam infinitas soluções e paralelas distintas indicam nenhuma solução.","y=x+1 e y=x+3 são paralelas e não se cruzam.","Duas retas coincidentes representam quantas soluções?",["Nenhuma","Uma","Infinitas"],2],["Determinante e solução única","Métodos matriciais","Para o sistema ax+by=e e cx+dy=f, o determinante D=ad−bc da matriz de coeficientes indica solução única quando D≠0. Se D=0, é necessário analisar a compatibilidade.","Para x+y=3 e x−y=1, D=−2, portanto há solução única.","Se D≠0, o sistema 2×2 tem:",["Uma solução","Nenhuma solução","Infinitas soluções"],0],["Regra de Cramer","Métodos matriciais","Em sistemas quadrados com determinante dos coeficientes D≠0, cada incógnita pode ser calculada pela razão entre o determinante obtido ao substituir sua coluna pelos termos independentes e D.","No sistema x+y=5 e x−y=1, a solução é x=3 e y=2.","A regra de Cramer exige:",["D=0","D≠0","Todas as incógnitas positivas"],1],["Problemas de preços","Aplicações","Para modelar problemas com dois produtos, atribua uma incógnita a cada preço, escreva as equações correspondentes às compras e resolva o sistema.","2 cadernos e 1 caneta custam R$ 11; 1 caderno e 1 caneta custam R$ 7. Caderno custa R$ 4.","Se x+y=15 e 2x+y=23, qual é x?",["7","8","9"],1],["Sistemas com três incógnitas","Aprofundamento","Um sistema 3×3 reúne três equações lineares em três incógnitas. É possível eliminar uma incógnita entre pares de equações, resolver um sistema 2×2 e substituir os resultados.","x+y+z=6, x+y=3 e x=1 → y=2, z=3.","Se x=2, x+y=5 e x+y+z=9, quanto vale z?",["3","4","5"],1]] as typeof highSchoolCatalog["Sistemas lineares"]));
highSchoolCatalog["Análise combinatória"].push(...([["Princípio fundamental da contagem","Princípios de contagem","Se uma escolha pode ocorrer de m formas e uma segunda, independentemente, de n formas, o total de resultados ordenados é m·n. Estenda a multiplicação para várias etapas.","3 camisetas, 2 calças e 4 tênis geram 3×2×4=24 looks.","Uma senha com 2 dígitos de 0 a 9, admitindo repetição, possui:",["20","100","90"],1],["Diagrama de árvore","Princípios de contagem","O diagrama de árvore organiza escolhas sucessivas em ramificações. Cada caminho completo representa um resultado possível, facilitando a contagem sem omissões.","Ao lançar duas moedas, os caminhos são CC, CK, KC e KK: 4 resultados.","Quantos resultados ordenados há ao lançar uma moeda e um dado?",["8","12","36"],1],["Fatorial","Fatoriais e permutações","Para n natural, n!=n(n−1)...2·1 e 0!=1. O fatorial conta as ordenações de n objetos distintos.","5!=5×4×3×2×1=120.","Quanto vale 4!?",["16","24","120"],1],["Permutação simples","Fatoriais e permutações","Uma permutação simples organiza todos os n elementos distintos em uma ordem. A quantidade de ordens possíveis é Pₙ=n!.","Quatro livros distintos podem ser ordenados em 4!=24 formas.","Quantas ordens existem para 3 pessoas em fila?",["3","6","9"],1],["Permutação com repetição","Fatoriais e permutações","Quando há elementos repetidos, dividimos o fatorial total pelos fatoriais das multiplicidades: n!/(a!b!...). Isso evita contar várias vezes arranjos idênticos.","A palavra ARARA tem 5 letras, com A três vezes e R duas: 5!/(3!2!)=10.","Quantos anagramas distintos tem ANA?",["3","6","2"],0],["Arranjos simples","Arranjos e combinações","Em arranjos de n elementos tomados p a p, a ordem importa e não há repetição. A(n,p)=n!/(n−p)!.","Entre 5 pessoas, presidente e vice podem ser escolhidos de 5×4=20 maneiras.","Quantos pódios de 3 posições existem entre 4 atletas?",["12","24","64"],1],["Combinações simples","Arranjos e combinações","Nas combinações, a ordem não importa. Para selecionar p objetos de n distintos, C(n,p)=n!/[p!(n−p)!].","Escolher 2 entre 5: C(5,2)=10.","Quantas comissões de 2 pessoas podem ser feitas com 6 pessoas?",["12","15","30"],1],["Distinguindo arranjo e combinação","Arranjos e combinações","Pergunte se trocar a ordem muda o resultado. Se muda, use arranjo; se não muda, combinação. Em ambos, identifique se há reposição.","Escolher presidente e vice entre 4 pessoas: 4×3=12; escolher uma dupla: C(4,2)=6.","Selecionar 3 alunos para uma equipe sem cargos é:",["Arranjo","Combinação","Permutação de todos"],1],["Contagem com restrições","Aplicações","Restrições alteram as opções disponíveis em cada etapa. Conte apenas as escolhas válidas, podendo dividir em casos que não se sobreponham.","Uma senha de dois algarismos distintos: 10 escolhas para o primeiro e 9 para o segundo, total 90.","Quantos números de dois algarismos, sem repetir dígitos, existem?",["81","90","100"],0],["Anagramas e aplicações","Aplicações","Anagramas são ordenações de letras. Para letras distintas, use fatorial; para repetidas, divida pelas multiplicidades. Regras como começar com vogal exigem contar por casos.","CASA: 4!/2!=12 anagramas distintos.","Quantos anagramas distintos tem OVO?",["3","6","2"],0]] as typeof highSchoolCatalog["Análise combinatória"]));
highSchoolCatalog["Probabilidade"].push(...([["Espaço amostral e evento","Fundamentos","O espaço amostral reúne todos os resultados possíveis de um experimento aleatório. Um evento é um subconjunto desse espaço. A probabilidade depende dos resultados que compõem o evento.","Dado: Ω={1,2,3,4,5,6}; evento par={2,4,6}.","Quantos resultados existem ao lançar um dado comum?",["3","6","12"],1],["Probabilidade clássica","Fundamentos","Em um espaço amostral finito com resultados equiprováveis, P(A)=n(A)/n(Ω). A probabilidade fica entre 0 e 1, inclusive.","Em um dado, P(par)=3/6=1/2.","Qual a probabilidade de tirar 5 em um dado honesto?",["1/5","1/6","5/6"],1],["Evento complementar","Operações com eventos","O complemento Aᶜ contém os resultados em que A não ocorre. Como A e Aᶜ cobrem todo o espaço amostral, P(Aᶜ)=1−P(A).","Se P(chover)=0,3, P(não chover)=0,7.","Se P(A)=0,25, quanto vale P(Aᶜ)?",["0,25","0,5","0,75"],2],["União de eventos","Operações com eventos","Para quaisquer eventos A e B, P(A∪B)=P(A)+P(B)−P(A∩B). Subtraímos a interseção para não contar resultados comuns duas vezes.","Dado: A={2,4,6}, B={4,5,6}; A∪B={2,4,5,6}, então P=4/6.","Se A e B são disjuntos, P(A)=0,2 e P(B)=0,3, P(A∪B) é:",["0,1","0,5","0,6"],1],["Interseção de eventos independentes","Operações com eventos","Eventos A e B são independentes quando a ocorrência de um não altera a probabilidade do outro. Nesse caso, P(A∩B)=P(A)·P(B).","Duas moedas honestas: P(duas caras)=1/2×1/2=1/4.","Qual a chance de duas caras em dois lançamentos independentes?",["1/2","1/4","1/8"],1],["Probabilidade condicional","Probabilidade condicional","Se P(B)>0, a probabilidade de A dado B é P(A|B)=P(A∩B)/P(B). O espaço de possibilidades fica restrito aos resultados de B.","Em um dado, sabendo que saiu par, a chance de sair 6 é 1/3.","Sabendo que o dado saiu par, qual a chance de sair 2?",["1/6","1/3","1/2"],1],["Eventos independentes e dependentes","Probabilidade condicional","Dois eventos são independentes se P(A|B)=P(A), quando P(B)>0. Em retiradas sem reposição, o primeiro resultado costuma alterar as probabilidades seguintes.","De uma urna com 3 bolas vermelhas e 2 azuis, após retirar uma vermelha sem reposição, restam 2 vermelhas em 4 bolas.","Qual é a chance de vermelha na segunda retirada, dado que a primeira foi vermelha?",["2/4","3/5","3/4"],0],["Distribuição binomial básica","Aplicações","Quando há n tentativas independentes com apenas sucesso ou fracasso e chance constante p, a probabilidade de k sucessos é C(n,k)pᵏ(1−p)ⁿ⁻ᵏ.","Duas moedas honestas: exatamente uma cara tem probabilidade C(2,1)(1/2)²=1/2.","Em duas moedas honestas, a chance de exatamente uma cara é:",["1/4","1/2","3/4"],1],["Probabilidade e porcentagem","Aplicações","Uma probabilidade pode ser expressa como fração, decimal ou percentual. Multiplique o valor decimal por 100 para obter a porcentagem.","P=3/20=0,15=15%.","Qual percentual equivale a 1/8?",["8%","12,5%","25%"],1]] as typeof highSchoolCatalog["Probabilidade"]));
highSchoolCatalog["Geometria espacial"].push(...([["Prismas e elementos","Poliedros","Prismas possuem duas bases poligonais paralelas e congruentes, ligadas por faces laterais. Em um prisma reto, a altura é perpendicular às bases.","Um prisma triangular possui 2 bases triangulares e 3 faces laterais.","Quantas bases possui um prisma?",["1","2","3"],1],["Volume de prismas","Poliedros","O volume de um prisma é V=A_base·h, com área da base e altura em unidades compatíveis. O resultado é expresso em unidades cúbicas.","Prisma com base de área 12 cm² e altura 5 cm: V=60 cm³.","Um prisma de base 8 cm² e altura 4 cm tem volume:",["12 cm³","32 cm³","64 cm³"],1],["Pirâmides e volume","Poliedros","Uma pirâmide tem base poligonal e faces laterais triangulares que se encontram em um vértice. Seu volume é um terço do produto da área da base pela altura.","Base de 18 cm² e altura 6 cm: V=18×6/3=36 cm³.","Uma pirâmide com base 12 cm² e altura 9 cm tem volume:",["36 cm³","54 cm³","108 cm³"],0],["Cilindros e volume","Corpos redondos","O cilindro circular reto possui duas bases circulares congruentes. Seu volume é V=πr²h, onde r é o raio e h é a altura.","r=2 cm, h=5 cm → V=20π cm³.","Um cilindro com r=3 e h=2 tem volume:",["6π","18π","36π"],1],["Cones e volume","Corpos redondos","O cone circular reto tem base circular e um vértice. Seu volume é V=πr²h/3, um terço do volume de um cilindro de mesma base e altura.","r=3, h=4 → V=π×9×4/3=12π.","Um cone de raio 2 e altura 6 tem volume:",["8π","12π","24π"],0],["Esferas e volume","Corpos redondos","Uma esfera é o conjunto de pontos do espaço a uma distância do centro menor ou igual ao raio, incluindo o interior. Seu volume é V=4πr³/3.","Para r=3, V=4π×27/3=36π.","Qual o volume de uma esfera de raio 1?",["4π/3","2π","4π"],0],["Área total de um cubo","Áreas de superfície","O cubo possui seis faces quadradas congruentes. Sua área total é seis vezes a área de uma face: A=6a², onde a é a aresta.","Aresta 4 cm: A=6×16=96 cm².","Qual a área total de um cubo de aresta 3 cm?",["27 cm²","54 cm²","81 cm²"],1],["Área lateral do cilindro","Áreas de superfície","Ao planificar a superfície lateral de um cilindro reto, obtemos um retângulo de comprimento 2πr e altura h. Assim, A_lateral=2πrh.","r=2, h=5 → A_lateral=20π.","Se r=3 e h=4, a área lateral é:",["12π","24π","36π"],1],["Relação de Euler","Poliedros","Em poliedros convexos, a relação de Euler é V−A+F=2, onde V representa vértices, A arestas e F faces. A fórmula auxilia a verificar contagens.","Um cubo tem V=8, A=12, F=6: 8−12+6=2.","Um poliedro convexo tem 8 vértices e 6 faces. Quantas arestas possui?",["10","12","14"],1],["Conversão de volume e capacidade","Aplicações","Um litro equivale a um decímetro cúbico e 1000 centímetros cúbicos. Para converter medidas de volume, considere que cada mudança de unidade cúbica envolve fator 1000.","2 dm³=2 L=2000 cm³.","Quantos litros correspondem a 3500 cm³?",["0,35 L","3,5 L","35 L"],1]] as typeof highSchoolCatalog["Geometria espacial"]));
Object.assign(catalog,highSchoolCatalog);
export const mathTopics=Object.keys(catalog);
export function getMathLessons(topic:string):MathLesson[]{return (catalog[topic]||[]).map(([title,module,body,example,question,options,correct])=>({title,module,body,example,question,options,correct}));}

/** Organização pedagógica sugerida; não remove nem duplica trilhas existentes. */
export const mathHighSchoolYears: Record<1|2|3, string[]> = {
  1: ["Conjuntos numéricos","Potenciação e radiciação","Produtos notáveis e fatoração","Equações e inequações","Função afim","Função quadrática","Razões e proporções"],
  2: ["Funções exponenciais e logarítmicas","Progressões PA e PG","Trigonometria","Matrizes e determinantes","Sistemas lineares","Análise combinatória","Probabilidade","Geometria espacial"],
  3: ["Geometria analítica","Números complexos","Polinômios","Estatística","Matemática financeira"]
};
export function getMathTopicsByYear(year: 1|2|3): string[] {
  return mathHighSchoolYears[year].filter(topic => mathTopics.includes(topic));
}
